// подставь максимальное n и сравни с ~10⁸ операций в секунду
static bool Fits(double ops, double seconds = 1) => ops <= 1e8 * seconds;

Fits(1e5 * 1e5);                  // n² при n = 10⁵: 10¹⁰ — false
Fits(1e5 * Math.Log(1e5, 2));     // n log n: ≈ 1,7·10⁶ — true
Fits(Math.Pow(2, 20) * 20);       // 2ⁿ·n при n = 20: ≈ 2·10⁷ — true

